<?php
namespace App\Console\Commands;
use App\Services\Shipping\Diagnostics\XpertaContractInspector;use Illuminate\Console\Command;use Illuminate\Support\Facades\Storage;
final class ShippingContractAuditCommand extends Command {protected $signature='zigo:shipping-contract-audit {--provider=all} {--environment=local} {--json} {--include-legacy}';protected $description='Audita callers y contratos shipping sin secretos.';public function handle(XpertaContractInspector $xperta):int{$provider=strtolower((string)$this->option('provider'));$environment=strtolower((string)$this->option('environment'));if(!in_array($provider,['estafeta','xperta','all'],true)||!in_array($environment,['local','stage','production'],true))return self::INVALID;$rows=[];if(in_array($provider,['xperta','all'],true)){$x=$xperta->inspect();foreach($x['contracts'] as $op=>$contract)$rows[]=$this->row('Xperta'.ucfirst($op).'Service',$op,$op,'estafeta','xperta',$contract['method']??null,'config',['Corporativo','x-api-key'],(array)($contract['request_keys']??[]),(array)($contract['response_keys']??[]),'config/services.php','B2C/API',$environment,($contract['confirmed']??false)?'active':'unknown',$contract['evidence']??null,($contract['confirmed']??false)?'confirmed':'unknown');}if(in_array($provider,['estafeta','all'],true)){$rows[]=$this->row('Estafeta','__construct','auth','estafeta','estafeta','POST','config',['Content-Type'],['grant_type','client_id','client_secret','scope'],['access_token','expires_in'],'LtdCredencial/LtdSesion','B2B/API',$environment,'legacy','app/Singlenton/Estafeta.php::__construct','confirmed');$rows[]=$this->row('EstafetaCreacion','validaLtdCobertura','coverage','estafeta','none',null,'database',[],['ltd_id','cp'],['extendida'],'LtdCobertura','B2C/B2B/API',$environment,'legacy','app/Negocio/Guias/EstafetaCreacion.php:794','confirmed');$rows[]=$this->row('EstafetaCreacion','soloCotizacion','quote','estafeta','none',null,'database',[],['ltd_id','servicio_id','cp','cp_d','peso','largo','ancho','alto'],['costo','costo_ae','sub_total','total'],'Tarifa/LtdCobertura','B2C/API',$environment,'active','app/Negocio/Guias/EstafetaCreacion.php:293','confirmed');}$report=['generated_at'=>now()->toIso8601String(),'provider'=>$provider,'environment'=>$environment,'include_legacy'=>(bool)$this->option('include-legacy'),'callers'=>$rows];$path='private/shipping-contract-audits/audit-'.now()->format('Ymd-His').'.json';Storage::disk('local')->put($path,json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));if($this->option('json'))$this->line(json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));else{$this->table(['operation','logical','http','method','status','confidence'],array_map(fn($r)=>[$r['operation'],$r['logical_provider'],$r['http_provider'],$r['http_method']??'-',$r['status'],$r['confidence']],$rows));$this->info('Reporte: storage/app/'.$path);}return self::SUCCESS;}private function row($class,$method,$operation,$logical,$http,$httpMethod,$urlSource,$headers,$request,$response,$credentials,$caller,$environment,$status,$evidence,$confidence):array{return['class'=>$class,'method'=>$method,'operation'=>$operation,'logical_provider'=>$logical,'http_provider'=>$http,'http_method'=>$httpMethod,'url_origin'=>$urlSource,'header_names'=>$headers,'request_keys'=>$request,'response_keys'=>$response,'credential_source'=>$credentials,'caller'=>$caller,'environment'=>$environment,'status'=>$status,'evidence'=>$evidence,'confidence'=>$confidence];}}
